import { Settings, importer, midi } from '@coderline/alphatab';
import { Midi } from '@tonejs/midi';

import { createImportedTrack } from './convert';
import { normalizeHeader } from './midi';
import { ImportedSong, MAX_IMPORT_NOTES, MelodyImportError } from './types';

export const parseGuitarProFile = (
  data: Uint8Array,
  filename: string,
): ImportedSong => {
  const settings = new Settings();
  settings.core.useWorkers = false;
  let score: ReturnType<typeof importer.ScoreLoader.loadScoreFromBytes>;
  try {
    score = importer.ScoreLoader.loadScoreFromBytes(data, settings);
  } catch {
    throw new MelodyImportError(
      'Не удалось прочитать Guitar Pro. Поддерживаются .gp3, .gp4, .gp5, .gpx и .gp.',
    );
  }
  const file = new midi.MidiFile();
  const captured = new Map<
    number,
    { pitch: number; start: number; length: number }[]
  >();
  let count = 0;
  // Capture before MIDI channel splitting, so bends and secondary channels
  // do not turn one Guitar Pro part into several selectable tracks.
  class Handler extends midi.AlphaSynthMidiFileHandler {
    addNote(
      track: number,
      start: number,
      length: number,
      key: number,
      velocity: number,
      channel: number,
    ) {
      if (++count > MAX_IMPORT_NOTES)
        throw new MelodyImportError(
          'В файле больше 50000 нот. Выберите файл с меньшим количеством партий.',
        );
      const notes = captured.get(track) ?? [];
      notes.push({ pitch: key, start: start + this.tickShift, length });
      captured.set(track, notes);
      super.addNote(track, start, length, key, velocity, channel);
    }
  }
  const handler = new Handler(file, true);
  new midi.MidiFileGenerator(score, settings, handler).generate();
  const header = new Midi(file.toBinary()).header;
  const metadata = normalizeHeader(header);
  const title = score.title.trim() || filename.replace(/\.[^.]+$/, '');
  const tracks = score.tracks
    .filter(track => captured.has(track.index))
    .map(track =>
      createImportedTrack({
        ...metadata,
        id: String(track.index),
        title,
        name: track.name.trim() || `Дорожка ${track.index + 1}`,
        author: score.artist.trim() || undefined,
        program: track.playbackInfo.program,
        percussion: track.staves.some(staff => staff.isPercussion),
        notes: captured.get(track.index)!.map(note => {
          const start = header.ticksToSeconds(note.start) * 1000;
          return {
            midi: note.pitch,
            start,
            duration:
              header.ticksToSeconds(note.start + note.length) * 1000 - start,
          };
        }),
      }),
    );
  if (!tracks.some(track => track.melody.notes.length))
    throw new MelodyImportError(
      'В Guitar Pro нет доступных нот в диапазоне C0–B8.',
    );
  return { title, format: 'Guitar Pro', tracks };
};
